package com.lifeos.habits.dto;import com.lifeos.habits.*;import java.time.*;public record HabitResponse(Long id,String name,String description,HabitFrequency frequency,Integer targetPerWeek,Integer currentStreak,Integer longestStreak,boolean active,LocalDateTime createdAt,LocalDateTime updatedAt){public static HabitResponse from(Habit h){return new HabitResponse(h.getId(),h.getName(),h.getDescription(),h.getFrequency(),h.getTargetPerWeek(),h.getCurrentStreak(),h.getLongestStreak(),h.isActive(),h.getCreatedAt(),h.getUpdatedAt());}}
